/// `referenceBondLength` (Angstrom); `kind` is the bond type of tagged entries.
pub fn gfn0_reference_bond_length(e0: &str, e1: &str, kind: Option<&str>) -> Option<f64> {
    match (e0, e1, kind) {
        ("C", "C", None) => Some(1.53),
        ("C", "N", None) => Some(1.42),
        ("C", "O", None) => Some(1.42),
        ("C", "H", None) => Some(1.1),
        ("N", "N", None) => Some(1.41),
        ("N", "O", None) => Some(1.4),
        ("N", "H", None) => Some(1.03),
        ("O", "O", None) => Some(1.45),
        ("O", "H", None) => Some(0.98),
        ("H", "H", None) => Some(0.8),
        ("C", "N", Some("triple")) => Some(1.16),
        ("C", "C", Some("triple")) => Some(1.2),
        ("C", "O", Some("double")) => Some(1.25),
        ("C", "N", Some("double")) => Some(1.29),
        _ => None,
    }
}

