/// `CNParams`.
pub fn gfn0_cnparams(e0: &str) -> Option<f64> {
    match e0 {
        "kStretch" => Some(0.9),
        "kBend" => Some(0.15),
        "kTorsion" => Some(0.002),
        _ => None,
    }
}

/// `GFN0Parameters.kCN`.
pub const GFN0_KCN: f64 = 2.0;
/// `GFN0Parameters.shellPoly`.
pub const GFN0_SHELLPOLY: f64 = 1.5;
/// `GFN0Parameters.kStretchBase`.
pub const GFN0_KSTRETCHBASE: f64 = 0.35;
/// `GFN0Parameters.kAngleBase`.
pub const GFN0_KANGLEBASE: f64 = 0.07;
/// `GFN0Parameters.V2Base`.
pub const GFN0_V2BASE: f64 = 0.00015936026415557387;
/// `GFN0Parameters.V3Base`.
pub const GFN0_V3BASE: f64 = 1.5936026415557385e-05;
